using SeedApi.Oauth;
using SeedApi;

var client = new SeedApiClient("client_id", "client_secret");
await client.Oauth.GetTokenAsync(
    new GetTokenRequest { ClientId = "client_id", ClientSecret = "client_secret" }
);

